# Generated by tux-theme ({{theme_name}}). Sourced by ~/.bashrc and tux-session.
export TUX_THEME="{{theme}}"
export BAT_THEME=ansi
export FZF_DEFAULT_OPTS="--height=60% --layout=reverse --border=sharp --info=inline \
  --color=bg+:{{bg_hl}},bg:-1,spinner:{{accent}},hl:{{accent}},fg:{{fg}},header:{{blue}},info:{{muted}} \
  --color=pointer:{{accent}},marker:{{green}},fg+:{{fg}},prompt:{{accent}},hl+:{{accent}},border:{{bg_hl}}"
